using System.IO;
using System.Net;

/// <summary>
/// MET Token Generator
/// </summary>
class METTokenGenerator
{
}

Method.Source:
/// <summary>
/// Generate OAuth token
/// </summary>
/// <param name = "clientId">Azure Client id</param>
/// <param name = "clientSecret">Azure Client id</param>
/// <param name = "tenantId">METcash tenantId id</param>
/// <returns>Token or error message</returns>
public static str generateOAuthToken(str clientId, str clientSecret, str tenantId)
{
    System.Net.Http.HttpClient       httpClient;
    System.Net.Http.StringContent    postData;
    System.Net.Http.HttpResponseMessage response;
    System.Text.Encoding             encoding;
    System.Exception                 exception;
    str                              requestUri, scope, responseBody, accessToken;

    try
    {
        httpClient = new System.Net.Http.HttpClient();

        requestUri = strFmt(METConstants::OAuthTokenUrl, tenantId);
        scope = strFmt(METConstants::APIDefaultUrl, tenantId);

        encoding = System.Text.Encoding::get_UTF8();
        postData = new System.Net.Http.StringContent(
            strFmt(METConstants::PostData,
                System.Uri::EscapeDataString(clientId),
                System.Uri::EscapeDataString(clientSecret),
                System.Uri::EscapeDataString(scope)),
                encoding,
                METConstants::BodyType);

        response = httpClient.PostAsync(requestUri, postData).get_Result();

        // Ensure success response
        if (!response.IsSuccessStatusCode)
        {
            throw error(strFmt("@MET:HttpError", response.StatusCode));
        }

        // Get response body
        responseBody = response.Content.ReadAsStringAsync().get_Result();

        // Parse token from response
        var jsonObject = System.Text.Json.JsonDocument::Parse(responseBody);
        var tokenElement = jsonObject.RootElement.GetProperty(METConstants::AccessToken);
        accessToken = tokenElement.GetString();
    }
    catch (Exception::CLRError)
    {
        System.Exception ex = ClrInterop::getLastException();
        if (ex != null)
        {
            ex = ex.get_InnerException();
            if (ex != null)
            {
                error(strFmt("@MET:ErrorFetchingToken", exception.get_Message()));
            }
        }
    }
    return accessToken;
}
